class Base:
    def __attrs_init_subclass__(cls, **kwargs):
        print(f"Base.__attrs_init_subclass__ called for {cls}")

def patch_attrs(cls):
    original_init_subclass = cls.__dict__.get("__init_subclass__", object.__init_subclass__)
    def __init_subclass__(subcls, **kwargs):
        original_init_subclass(subcls, **kwargs)
        if hasattr(subcls, "__attrs_init_subclass__"):
            subcls.__attrs_init_subclass__(**kwargs)
    cls.__init_subclass__ = __init_subclass__

patch_attrs(Base)

class Sub(Base):
    pass

print("Sub created")

class SubSub(Sub):
    def __attrs_init_subclass__(cls, **kwargs):
        print(f"SubSub.__attrs_init_subclass__ called for {cls}")

patch_attrs(Sub) # Sub is also patched

class SubSubSub(SubSub):
    pass

print("SubSubSub created")

